 import { gsap } from 'gsap';
import { MeshBasicNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import { uv, mix, smoothstep, color as tslColor } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry, CircleGeometry, DirectionalLight, PointLight, Box3, Vector3, FrontSide } = ctx.THREE;

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const meshUrl = config.meshUrl ?? config.intent?.visualSpec?.meshUrl;
  const tlStore = [];

  const root = new Group();
  root.name = config.id ?? 'home-ornamental-divider';

  // Stage backdrop with vertical ink-to-surface gradient.
  const gradientNode = mix(
    tslColor(colors.surface),
    tslColor(colors.ink),
    smoothstep(0.0, 1.0, uv().y)
  );

  const backdropMat = new MeshBasicNodeMaterial({
    colorNode: gradientNode,
    side: FrontSide
  });

  const backdrop = new Mesh(new PlaneGeometry(2.6, 1.7), backdropMat);
  backdrop.position.set(0, 0, -0.35);
  backdrop.name = 'divider-backdrop';
  root.add(backdrop);

  // Content group (hovered/pressed).
  const content = new Group();
  content.name = 'divider-content';
  root.add(content);

  // Contact shadow on ground plane.
  const shadowMat = new MeshBasicNodeMaterial({
    color: colors.surface,
    transparent: true,
    opacity: 0.45,
    depthWrite: false
  });
  const shadow = new Mesh(new CircleGeometry(0.55, 32), shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -0.75, 0.02);
  shadow.name = 'divider-shadow';
  root.add(shadow);

  // Rim / accent lighting.
  const keyLight = new DirectionalLight(colors.paper, 1.1);
  keyLight.position.set(-1.2, 2.0, 2.0);
  root.add(keyLight);

  const rimLight = new PointLight(colors.accent, 0.9, 6.0);
  rimLight.position.set(1.2, 0.4, 1.2);
  root.add(rimLight);

  // Focus accent edge frame (built after GLB load).
  let focusFrame = null;

  if (meshUrl) {
    ctx.glbLoader.loadGLB(meshUrl).then((gltf) => {
      const scene = gltf.scene;
      scene.name = 'divider-mesh';

      const box = new Box3().setFromObject(scene);
      const center = new Vector3();
      const size = new Vector3();
      box.getCenter(center);
      box.getSize(size);

      scene.position.sub(center);
      content.add(scene);

      // Fit contact shadow to mesh footprint.
      const footprint = Math.max(size.x, size.z) * 0.7;
      shadow.scale.set(footprint, footprint, 1);
      shadow.position.y = -size.y * 0.5 - 0.02;

      // Accent focus frame.
      focusFrame = buildFocusFrame(size.x + 0.08, size.y + 0.08, size.z + 0.04);
      focusFrame.visible = false;
      content.add(focusFrame);
    }).catch((err) => {
      // eslint-disable-next-line no-console
      console.warn('Divider GLB load failed:', err);
    });
  }

  function buildFocusFrame(w, h, d) {
    const group = new Group();
    group.name = 'divider-focus-frame';
    const t = 0.012;
    const mat = new MeshBasicNodeMaterial({ color: colors.accent });
    mat.transparent = true;
    mat.opacity = 0.9;

    // Front face frame.
    const top = new Mesh(new BoxGeometry(w, t, t), mat);
    top.position.set(0, h * 0.5, d * 0.5);
    const bottom = new Mesh(new BoxGeometry(w, t, t), mat);
    bottom.position.set(0, -h * 0.5, d * 0.5);
    const left = new Mesh(new BoxGeometry(t, h, t), mat);
    left.position.set(-w * 0.5, 0, d * 0.5);
    const right = new Mesh(new BoxGeometry(t, h, t), mat);
    right.position.set(w * 0.5, 0, d * 0.5);

    group.add(top, bottom, left, right);
    return group;
  }

  function hoverIn() {
    gsap.killTweensOf(content.position);
    gsap.to(content.position, {
      y: 0.15,
      duration: 0.35,
      ease: 'power2.out'
    });
  }

  function hoverOut() {
    gsap.killTweensOf(content.position);
    gsap.to(content.position, {
      y: 0,
      duration: 0.35,
      ease: 'power2.out'
    });
  }

  function pressDown() {
    gsap.killTweensOf(content.scale);
    gsap.to(content.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'back.out(1.7)'
    });
  }

  function pressUp() {
    gsap.killTweensOf(content.scale);
    gsap.to(content.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.2,
      ease: 'power2.out'
    });
  }

  function setFocus(active) {
    if (focusFrame) focusFrame.visible = active;
  }

  root.userData.handlers = {
    pointerenter: hoverIn,
    pointerleave: hoverOut,
    hover: hoverIn,
    hoverOut: hoverOut,
    pointerdown: pressDown,
    pointerup: pressUp,
    focus: () => setFocus(true),
    blur: () => setFocus(false),
    click: () => {
      pressDown();
      ctx.emit('hub-home.select', {});
      setTimeout(() => pressUp(), 140);
    }
  };

  function disposeMaterial(mat) {
    if (!mat) return;
    if (Array.isArray(mat)) {
      mat.forEach(disposeMaterial);
      return;
    }
    if (mat.map) mat.map.dispose();
    if (mat.normalMap) mat.normalMap.dispose();
    if (mat.roughnessMap) mat.roughnessMap.dispose();
    if (mat.metalnessMap) mat.metalnessMap.dispose();
    if (mat.emissiveMap) mat.emissiveMap.dispose();
    mat.dispose();
  }

  function disposeObject(obj) {
    obj.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) disposeMaterial(child.material);
    });
  }

  root.userData.cleanup = () => {
    gsap.killTweensOf(content.position);
    gsap.killTweensOf(content.scale);

    disposeObject(root);
    keyLight.dispose();
    rimLight.dispose();
  };

  return root;
}
